  'Open server in browser': { id: 'Buka server di peramban', 'zh-CN': '在浏览器中打开服务器', es: 'Abrir servidor en el navegador', ar: 'فتح الخادم في المتصفح' },
  'Offline file installed': { id: 'File luring terpasang', 'zh-CN': '已安装离线文件', es: 'Archivo sin conexión instalado', ar: 'تم تثبيت ملف دون اتصال' },
