export function translateUi(locale: Locale, source: string, variables?: Record<string, string | number>): string {
  const template = locale === 'en' ? source : UI_TEXT[source]?.[locale] ?? source;
  return variables ? template.replace(/\{(\w+)\}/g, (match, name: string) => String(variables[name] ?? match)) : template;
}

export function useUiText() {
  const locale = useLocaleStore((state) => state.locale);
  return (source: string, variables?: Record<string, string | number>) => translateUi(locale, source, variables);
}
